请对以下 case 进行三维加权评分。

=== case_id ===
Case-30-pet-feeder-017

=== 用户原始指令 (query.txt) ===
想做一张宠物活力卡,主视觉用素材库里的猫爪图标,中间大字显示活力值85(动态那种),右侧动作区"播放助眠歌单"按钮点开跳到音乐app的指定歌单。读一下今天天气23度适不适合带它出门。底色左右不同(浅绿和米白),整张走绿到青的活力渐变,状态用绿色"活力充沛·可互动"。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "想做一张宠物活力卡,主视觉用素材库里的猫爪图标,中间大字显示活力值85(动态那种),右侧动作区\"播放助眠歌单\"按钮点开跳到音乐app的指定歌单。读一下今天天气23度适不适合带它出门。底色左右不同(浅绿和米白),整张走绿到青的活力渐变,状态用绿色\"活力充沛·可互动\"。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "pet": {
      "vitalityText": {
        "type": "string",
        "description": "宠物当前活力值展示文本。",
        "sampleValue": "85"
      },
      "statusText": {
        "type": "string",
        "description": "宠物当前活力状态提示。",
        "sampleValue": "活力充沛·可互动"
      },
      "outdoorAdvice": {
        "type": "string",
        "description": "结合今日天气给出的宠物外出建议。",
        "sampleValue": "适合出门"
      }
    },
    "data": {
      "weather": {
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "23°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    },
    "ui": {
      "actionTitle": {
        "type": "string",
        "description": "音乐歌单动作区的对象说明。",
        "sampleValue": "助眠歌单"
      },
      "actionLabel": {
        "type": "string",
        "description": "音乐歌单跳转动作按钮文案。",
        "sampleValue": "播放"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/heart_fill.svg",
      "description": "心形实心图标，适合表达宠物关怀、健康与活力状态，可作为宠物活力主视觉替代图标。"
    }
  ]
}

